function response(body, contentType) {
  return new Response(body, { headers: { "content-type": contentType, "cache-control": "no-store" } });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname in assets) {
      return response(assets[url.pathname], url.pathname.endsWith(".css") ? "text/css; charset=utf-8" : "text/javascript; charset=utf-8");
    }
    if (url.pathname === "/pixel-agents" || url.pathname === "/pixel-agents/") {
      return response(pixelAgents, "text/html; charset=utf-8");
    }
    return response(html, "text/html; charset=utf-8");
  }
};
